// Small vector / quaternion / random helpers. Quaternions are [w, x, y, z].

export const add3 = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
export const scale3 = (a, k) => [a[0] * k, a[1] * k, a[2] * k];
export const dot3 = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
export const norm3 = (a) => Math.hypot(a[0], a[1], a[2]);
export const cross3 = (a, b) => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
export const unit3 = (a) => {
  const n = norm3(a);
  return n > 1e-12 ? scale3(a, 1 / n) : [0, 0, 0];
};

export function qmul(a, b) {
  const [aw, ax, ay, az] = a;
  const [bw, bx, by, bz] = b;
  return [
    aw * bw - ax * bx - ay * by - az * bz,
    aw * bx + ax * bw + ay * bz - az * by,
    aw * by - ax * bz + ay * bw + az * bx,
    aw * bz + ax * by - ay * bx + az * bw,
  ];
}
export const qconj = (q) => [q[0], -q[1], -q[2], -q[3]];
export function qnormalize(q) {
  const n = Math.hypot(q[0], q[1], q[2], q[3]) || 1;
  return [q[0] / n, q[1] / n, q[2] / n, q[3] / n];
}
/** Rotate vector v by unit quaternion q. */
export function qrotate(q, v) {
  const r = qmul(qmul(q, [0, v[0], v[1], v[2]]), qconj(q));
  return [r[1], r[2], r[3]];
}
/** Quaternion -> rotation vector (axis * angle, radians). */
export function qToRotVec(q) {
  let [w, x, y, z] = q;
  if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
  const s = Math.hypot(x, y, z);
  if (s < 1e-9) return [2 * x, 2 * y, 2 * z];
  const k = (2 * Math.atan2(s, w)) / s;
  return [x * k, y * k, z * k];
}
/** Rotation vector -> unit quaternion. */
export function rotVecToQ(v) {
  const angle = norm3(v);
  if (angle < 1e-12) return [1, v[0] / 2, v[1] / 2, v[2] / 2];
  const s = Math.sin(angle / 2) / angle;
  return [Math.cos(angle / 2), v[0] * s, v[1] * s, v[2] * s];
}
/** Normalized lerp with hemisphere fix — fine for the small steps between samples. */
export function qnlerp(a, b, f) {
  const sign = a[0] * b[0] + a[1] * b[1] + a[2] * b[2] + a[3] * b[3] < 0 ? -1 : 1;
  return qnormalize([
    a[0] + (sign * b[0] - a[0]) * f,
    a[1] + (sign * b[1] - a[1]) * f,
    a[2] + (sign * b[2] - a[2]) * f,
    a[3] + (sign * b[3] - a[3]) * f,
  ]);
}

/** 3x3 rotation matrix (row-major array of rows) from a rotation vector (Rodrigues). */
export function rotVecToMat(v) {
  const angle = norm3(v);
  if (angle < 1e-12) return [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
  const [x, y, z] = scale3(v, 1 / angle);
  const c = Math.cos(angle), s = Math.sin(angle), t = 1 - c;
  return [
    [t * x * x + c, t * x * y - s * z, t * x * z + s * y],
    [t * x * y + s * z, t * y * y + c, t * y * z - s * x],
    [t * x * z - s * y, t * y * z + s * x, t * z * z + c],
  ];
}
export const matVec = (m, v) => [dot3(m[0], v), dot3(m[1], v), dot3(m[2], v)];

/** Rotation matrix that takes direction `from` onto direction `to`. */
export function alignMat(from, to) {
  const f = unit3(from), t = unit3(to);
  const axis = cross3(f, t);
  const s = norm3(axis);
  const c = dot3(f, t);
  if (s < 1e-9) {
    if (c > 0) return rotVecToMat([0, 0, 0]);
    // Opposite: rotate 180° about any axis perpendicular to f.
    const perp = Math.abs(f[0]) < 0.9 ? unit3(cross3(f, [1, 0, 0])) : unit3(cross3(f, [0, 1, 0]));
    return rotVecToMat(scale3(perp, Math.PI));
  }
  return rotVecToMat(scale3(axis, Math.atan2(s, c) / s));
}

/** Deterministic PRNG so augmentation and permutation tests are reproducible. */
export function mulberry32(seed) {
  let a = seed >>> 0;
  const rng = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  rng.normal = () => {
    const u = Math.max(rng(), 1e-12), v = rng();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  rng.uniform = (lo, hi) => lo + (hi - lo) * rng();
  rng.unitVector = () => unit3([rng.normal(), rng.normal(), rng.normal()]);
  return rng;
}

export function hashString(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

export function median(values) {
  if (!values.length) return 0;
  const s = [...values].sort((a, b) => a - b);
  return s[Math.floor(s.length / 2)];
}
